@deployment
container cloud "本番環境" [layout=column] {
 container front "入口" [layout=row] {
  node cdn "CDN"
  node gw "Gateway"
 }
 container apps "アプリケーション" [layout=row] {
  server api "注文API"
  server worker "非同期Worker"
 }
 container data "データ層" [layout=row] {
  database db "注文DB"
  node queue "Queue"
 }
}
cdn -> gw: HTTPS
gw -> api: 転送
api -> db: 保存
api -> queue: 配信
queue -> worker: 購読
worker -> db: 更新

@er
entity customers "顧客" {
 id UUID pk
 name string
}
entity orders "注文" {
 id UUID pk
 customer_id UUID fk
}
entity items "注文明細" {
 id UUID pk
 order_id UUID fk
 product_id UUID fk
}
entity products "商品" {
 id UUID pk
 name string
}
entity payments "支払い" {
 id UUID pk
 order_id UUID fk
}
customers 1 -> many orders: 発注
orders 1 -> many items: 明細
products 1 -> many items: 対象
orders 1 -> many payments: 決済

@class
interface Repository {
 +save(): void
}
class OrderRepository {
 +save(): void
}
class CustomerRepository {
 +save(): void
}
class Order {
 -id: UUID
 +submit(): void
}
class LineItem {
 -quantity: int
}
OrderRepository ..|> Repository
CustomerRepository ..|> Repository
OrderRepository --> Order: 保存
Order "1" *-- "1..N" LineItem: 明細
